# ruff: noqa: E501
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from newsintel.api.dependencies import SourceManagerAuth
from newsintel.api.ui import COMMON_JS, render_app_page

router = APIRouter(tags=["dashboard"])


@router.get("/news-sources", response_class=HTMLResponse)
async def news_sources_dashboard(auth: SourceManagerAuth) -> str:
    body = r"""
<section class="page-head"><div><div class="eyebrow">Source operations</div><h1>Sources</h1><p class="lead">Add approved publishers, inspect feed health and review fetch or extraction problems.</p></div><div class="toolbar"><a class="button secondary" href="/news">Open news</a><button id="fetchAllBtn" type="button">Fetch all active publishers</button></div></section>
<section class="grid four" id="sourceMetrics"><div class="metric"><div class="label">Publishers</div><div class="value" id="mSources">—</div></div><div class="metric"><div class="label">Extracted</div><div class="value" id="mTotalExtracted">—</div></div><div class="metric"><div class="label">Failed</div><div class="value" id="mTotalFailed">—</div></div><div class="metric"><div class="label">Active sources</div><div class="value" id="mActive">—</div></div></section>
<section class="panel" style="margin-top:18px"><details id="addSourcePanel"><summary style="cursor:pointer;font-weight:800">Add or discover a publisher</summary><div class="grid two" style="margin-top:16px"><label>Publisher name<input id="publisherName" placeholder="BBC News" /></label><label>Website URL<input id="websiteUrl" type="url" placeholder="https://www.bbc.com/news" /></label><label>Fetch frequency<select id="fetchFrequency"><option value="manual">Manual</option><option value="every_15_minutes">Every 15 minutes</option><option value="hourly" selected>Hourly</option><option value="every_6_hours">Every 6 hours</option><option value="daily">Daily</option></select></label><label>Manual RSS/sitemap fallback<textarea id="manualEndpoints" placeholder="One URL per line"></textarea></label></div><div class="toolbar" style="margin-top:14px"><button id="discoverBtn" type="button">Discover and add</button><span id="addStatus" class="muted small" aria-live="polite"></span></div></details></section>
<section class="panel" style="margin-top:18px"><div class="section-head"><div><h2>Publisher health</h2><div class="muted small">Discovery, extraction and fetch status by source.</div></div><div class="toolbar"><input id="sourceSearch" type="search" placeholder="Filter publishers…" style="min-width:220px" /><button class="secondary" id="refreshSourcesBtn" type="button">Refresh</button></div></div><div id="sourcesArea"><div class="skeleton" style="height:220px"></div></div></section>
<dialog id="disablePublisherDialog" aria-labelledby="disablePublisherTitle"><div class="dialog-card" style="display:grid;gap:14px;min-width:min(440px,calc(100vw - 44px))"><h2 id="disablePublisherTitle">Disable publisher</h2><p id="disablePublisherName" class="muted"></p><p class="muted small">This stops discovery and article fetching for the selected publisher. Previously captured reports remain available.</p><div class="toolbar"><button id="confirmDisablePublisher" class="danger" type="button">Disable publisher</button><button id="cancelDisablePublisher" class="ghost" type="button">Cancel</button></div></div></dialog>
<section class="panel" style="margin-top:18px"><div class="section-head"><div><h2>Current fetch</h2><div id="jobLine" class="muted small">No fetch job selected.</div></div></div><div class="grid four"><div class="metric"><div class="label">Publishers</div><div class="value" id="jPublishers">0</div></div><div class="metric"><div class="label">URLs discovered</div><div class="value" id="jUrls">0</div></div><div class="metric"><div class="label">Articles extracted</div><div class="value" id="jExtracted">0</div></div><div class="metric"><div class="label">Failed</div><div class="value" id="jFailed">0</div></div></div><div class="pill-row" style="margin-top:12px"><span class="pill neutral" id="jQueued">0 queued</span><span class="pill neutral" id="jDuplicates">0 duplicates</span></div></section>
"""
    scripts = f"""<script>{COMMON_JS}
let sources=[];let currentJobId=null;let pollHandle=null;
function badge(value){{const v=String(value||'unknown');const kind=['ready','active','complete'].includes(v)?'good':v==='failed'?'bad':'warn';return niPill(niTitle(v),kind)}}
function renderSources(){{const q=document.getElementById('sourceSearch').value.trim().toLowerCase();const rows=sources.filter(s=>!q||[s.name,s.canonical_domain,s.discovery_status,s.current_status].some(v=>String(v||'').toLowerCase().includes(q)));document.getElementById('mSources').textContent=sources.length;document.getElementById('mTotalExtracted').textContent=sources.reduce((n,s)=>n+(s.articles_extracted||0),0);document.getElementById('mTotalFailed').textContent=sources.reduce((n,s)=>n+(s.failed_articles||0),0);document.getElementById('mActive').textContent=sources.filter(s=>['active','ready'].includes(s.current_status)).length;const area=document.getElementById('sourcesArea');if(!rows.length){{area.innerHTML='<div class="empty">No publishers match this filter.</div>';return}}area.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Publisher</th><th>Discovery</th><th>Channels</th><th>Last successful check</th><th>Articles</th><th>Status</th><th>Actions</th></tr></thead><tbody>${{rows.map(s=>`<tr><td><b>${{niEsc(s.name)}}</b><div class="muted small">${{niEsc(s.canonical_domain)}}</div>${{s.homepage_url?`<a class="small" href="${{niEsc(niSafeUrl(s.homepage_url))}}" target="_blank" rel="noopener noreferrer">Open website</a>`:''}}</td><td>${{badge(s.discovery_status)}}<div class="muted small">${{niEsc(s.discovery_message||'')}}</div></td><td>${{s.rss_feed_count||0}} feeds · ${{s.sitemap_count||0}} sitemaps</td><td>${{niDate(s.last_fetched_at)}}<div class="muted small">${{niTitle(s.fetch_frequency)}}</div></td><td><b>${{s.articles_extracted||0}}</b> extracted<div class="muted small">${{s.articles_discovered||0}} discovered · ${{s.failed_articles||0}} failed · ${{s.rejected_articles||0}} excluded<br>Latest saved: ${{s.last_article_at?niRelative(s.last_article_at):'none yet'}}</div></td><td>${{badge(s.current_status)}}</td><td><div class="toolbar"><button type="button" onclick="fetchPublisher('${{s.id}}')">Fetch</button><button class="secondary" type="button" onclick="prefill('${{niEsc(s.id)}}')">Reconfigure</button><button class="danger" type="button" onclick="deletePublisher('${{s.id}}')">Disable</button></div></td></tr>`).join('')}}</tbody></table></div>`}}
async function loadSources(){{try{{sources=await niApi('/api/v1/publishers');renderSources()}}catch(e){{document.getElementById('sourcesArea').innerHTML=`<div class="error-box">${{niEsc(e.message)}}</div>`}}}}
function prefill(id){{const s=sources.find(x=>x.id===id);if(!s)return;document.getElementById('publisherName').value=s.name;document.getElementById('websiteUrl').value=s.homepage_url||'';document.getElementById('fetchFrequency').value=s.fetch_frequency;document.getElementById('addSourcePanel').open=true;document.getElementById('addStatus').textContent='Reconfiguration pre-fills this discovery form. Stored endpoints are not edited in place yet; disable and re-add only when you intentionally want to replace them.';document.getElementById('publisherName').focus()}}
async function discoverAndAdd(){{const btn=document.getElementById('discoverBtn'),status=document.getElementById('addStatus');const name=document.getElementById('publisherName').value.trim(),url=document.getElementById('websiteUrl').value.trim();if(!name||niSafeUrl(url)==='#'){{status.textContent='Enter a publisher name and valid HTTP/HTTPS website URL.';return}}btn.disabled=true;status.textContent='Discovering feeds, sitemaps and sections…';try{{const manual=document.getElementById('manualEndpoints').value.split('\\n').map(x=>x.trim()).filter(Boolean);const r=await niApi('/api/v1/publishers/discover',{{method:'POST',body:JSON.stringify({{publisher_name:name,website_url:url,fetch_frequency:document.getElementById('fetchFrequency').value,manual_endpoints:manual}})}});status.textContent=`Added ${{r.publisher.name}} · ${{r.valid_endpoint_count}} valid channels.`;niToast(`Added ${{r.publisher.name}}`);await loadSources()}}catch(e){{status.textContent=`Failed: ${{e.message}}`}}finally{{btn.disabled=false}}}}
async function fetchPublisher(id){{try{{const r=await niApi(`/api/v1/publishers/${{id}}/fetch`,{{method:'POST'}});watchJob(r.job_id);niToast('Fetch started');await loadSources()}}catch(e){{niToast(e.message,'bad')}}}}
async function fetchAll(){{const btn=document.getElementById('fetchAllBtn');btn.disabled=true;try{{const r=await niApi('/api/v1/fetch/all',{{method:'POST'}});watchJob(r.job_id);niToast('Fetch-all started')}}catch(e){{niToast(e.message,'bad')}}finally{{btn.disabled=false}}}}
let pendingPublisherDisable=null;
function deletePublisher(id){{const source=sources.find(s=>s.id===id);pendingPublisherDisable=id;document.getElementById('disablePublisherName').textContent=source?source.name:'Selected publisher';document.getElementById('disablePublisherDialog').showModal()}}
async function confirmPublisherDisable(){{if(!pendingPublisherDisable)return;const id=pendingPublisherDisable,btn=document.getElementById('confirmDisablePublisher');btn.disabled=true;try{{await niApi(`/api/v1/publishers/${{id}}`,{{method:'DELETE'}});document.getElementById('disablePublisherDialog').close();pendingPublisherDisable=null;niToast('Publisher disabled','good');await loadSources()}}catch(e){{niToast(e.message,'bad')}}finally{{btn.disabled=false}}}}
document.getElementById('confirmDisablePublisher').addEventListener('click',confirmPublisherDisable);
document.getElementById('cancelDisablePublisher').addEventListener('click',()=>document.getElementById('disablePublisherDialog').close());
function watchJob(id){{currentJobId=id;clearInterval(pollHandle);pollJob();pollHandle=setInterval(pollJob,2500)}}async function pollJob(){{if(!currentJobId)return;try{{const j=await niApi(`/api/v1/fetch-jobs/${{currentJobId}}`);document.getElementById('jobLine').textContent=`${{niTitle(j.status)}} · ${{j.channels_remaining||0}} channels left · ${{j.pending_articles||0}} articles waiting · ${{j.message||''}}`;document.getElementById('jPublishers').textContent=`${{j.publishers_processed}}/${{j.publishers_total}}`;document.getElementById('jUrls').textContent=j.urls_discovered;document.getElementById('jExtracted').textContent=j.articles_extracted;document.getElementById('jFailed').textContent=j.failed_articles;document.getElementById('jQueued').textContent=`${{j.articles_queued}} queued`;document.getElementById('jDuplicates').textContent=`${{j.duplicates_skipped}} duplicates`;if(['completed','failed','cancelled'].includes(j.status)){{clearInterval(pollHandle);pollHandle=null;await loadSources()}}}}catch(e){{document.getElementById('jobLine').textContent=`Fetch status unavailable: ${{e.message}}`}}}}
document.getElementById('discoverBtn').addEventListener('click',discoverAndAdd);document.getElementById('fetchAllBtn').addEventListener('click',fetchAll);document.getElementById('refreshSourcesBtn').addEventListener('click',loadSources);document.getElementById('sourceSearch').addEventListener('input',niDebounce(renderSources,100));loadSources();setInterval(()=>{{if(!document.hidden)loadSources()}},15000);
</script>"""
    return render_app_page(title="Sources", body=body, active="sources", role=getattr(getattr(auth, "role", None), "value", "source_manager"), scripts=scripts)
